insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
insert into public.procedimientos (numero, titulo, objeto, alcance, responsable, condicionantes, pasos, equipo) values ('01', 'COMPROBACIÓN DE ESTRUCTURA SOPORTE', 'La finalidad de esta prueba es comprobar el estado de la estructura soporte y sus componentes con el fin de comprobar la correcta integridad de la instalación. La inspección abarcará tanto elementos metálicos como plásticos.', 'La totalidad de la estructura soporte y sus componentes.', 'Trabajador cualificado.', 'Para realizar esta comprobación, será necesario disponer de las especificaciones de montaje mecánico de la estructura y los criterios de apriete de la misma.', ARRAY['Se revisarán los siguientes puntos:', 'Mediante inspección visual:', 'Comprobar que la cimentación de la estructura y/o la superficie de sustentación de la misma no muestran signos de deterioro (grietas, desprendimientos de material, oxido...etc.). En su caso, proceder a repararlo con la obra civil necesaria para asegurar la reparación del estado de deterioro correspondiente', 'Comprobar que las uniones y anclajes de la estructura no muestran signos de holgura o aflojamiento que puedan provocar vibraciones por efecto del viento. En su caso, proceder a dar el par de apriete correspondiente para la métrica del tornillo según las instrucciones del fabricante', 'Comprobar mediante inspección visual que los elementos de la estructura no sufren deformaciones (provocadas por los esfuerzos soportados) no especificadas en el análisis estructural efectuado en la fase de diseño', 'Se comprobara que en la estructura mecánica, las uniones están ejecutadas según especificación del fabricante, respetando los pares de apriete que se indiquen en el procedimiento de montaje del mismo', 'Se comprobará que el cableado discurre en bandejas o tubos. Así mismo, se comprobará que no existe cableado instalado sin protección en las zonas con aristas metálicas. Los tubos y canalizaciones deben ser resistentes a la intemperie', 'Se comprobará la correcta colocación de todos los paneles y el correcto conexionado de los mismos', 'Se comprobará que no puede haber elementos que produzcan sombras en ningún momento del año'], '{"Equipos de seguridad": ["Casco.", "Calzado de seguridad.", "Guantes de trabajo."], "Herramientas": ["Procedimientos de trabajo para mantenimiento preventivo en plantas f.v.", "Registros de inspección para mantenimiento preventivo en plantas f.v.", "Documentación técnica de la instalación.", "Juego de herramientas de mano aisladas (juego de destornilladores, juego de llaves", "fijas y de carraca, juego de alicates, tijeras, etc.).", "Escalera.", "Llaves dinamométricas desde 8Nm hasta 200Nm."], "Equipos de limpieza y material consumible": ["Guantes de látex.", "Tortillería variada.", "Pintura esmalte.", "Pintura de galvanizado en frío.", "Protección contra corrosión. (Tectyl 120 CGW o similar).", "Bridas de plástico.", "13"]}'::jsonb) on conflict (numero) do nothing;
insert into public.procedimientos (numero, titulo, objeto, alcance, responsable, condicionantes, pasos, equipo) values ('02', 'COMPROBACIÓN DE LAS CANALIZACIONES DE LOS CABLES ENTERRADOS', 'El objeto de esta comprobación es verificar que todas las canalizaciones, conexiones e interconexiones eléctricas de la instalación se encuentran en buen estado.', 'Todas las canalizaciones de cableado eléctrico de la planta.', 'Personal cualificado.', 'No existe ningún condicionante especial.', ARRAY['Comprobar que los conductos de protección y las canalizaciones se encuentran en perfecto estado, sin signos de deterioro ni defectos de aislamiento o estanqueidad. En su caso, reemplazar o reparar el elemento afectado, según sea el alcance o la importancia del daño', 'Comprobar que las bridas de sujeción de los conductores tendidos al aire, los conductos de protección y las canalizaciones se encuentran en buen estado', 'Comprobar la fijación de los soportes, bandejas y limpieza o deterioro de los mismos', 'Comprobar en las zonas visibles que el cable no está perforado, rajado ni con daños mecánicos en la cubierta por roces con aristas', 'Se comprobará el correcto estado de las arquetas', 'Localización de todos los empalmes chequeando que están registrables mediante arquetas adecuadas, que hay separación mínima entre empalmes, que no existen daños en la cubierta, acumulaciones de aire entre cubierta y aislamiento, hilos de la malla visibles, deformidades sospechosas y cualquier otro posible problema'], '{"Equipos de seguridad": ["Casco.", "Calzado de seguridad.", "Guantes de trabajo.", "Guantes aislantes."], "Herramientas": ["Procedimientos de trabajo para mantenimiento preventivo en plantas f.v.", "Registros de inspección para mantenimiento preventivo en plantas f.v.", "Documentación técnica de la instalación.", "Juego de herramientas de mano aisladas (juego de destornilladores, juego de llaves", "fijas y de carraca, juego de alicates, tijeras, etc.).", "Linterna.", "Escalera.", "Llaves dinamométricas desde 8Nm hasta 200Nm."], "Equipos de limpieza y material consumible": ["Cinta aislante.", "Pintura de galvanizado en frío.", "Cinta selladora.", "Bridas de plástico.", "15"]}'::jsonb) on conflict (numero) do nothing;
insert into public.procedimientos (numero, titulo, objeto, alcance, responsable, condicionantes, pasos, equipo) values ('03', 'COMPROBACIÓN DEL ESTADO DE ESTANQUEIDAD Y CONSERVACIÓN DE LAS CAJAS DE PARALELOS Y CONDUCTORES ELECTRICOS', 'El objeto de esta revisión es comprobar que las cajas de paralelos presentan un perfecto estado, están completamente aisladas de cualquier tipo de inclemencia atmosférica que pueda interferir en el buen funcionamiento de la instalación.', 'La totalidad de las cajas de conexión.', 'Personal cualificado.', 'Para realizar esta comprobación, será necesario disponer de un plano de conexionado serie y paralelo del campo FV.', ARRAY['Comprobar que los conductos de protección y las canalizaciones se encuentran en perfecto estado, sin signos de deterioro ni defectos de aislamiento o estanqueidad. En su caso, reemplazar o reparar el elemento afectado, según sea el alcance o la importancia del daño', 'Observar que las bridas de sujeción de los conductores tendidos al aire, los conductos de protección y las canalizaciones se encuentran en buen estado', 'Comprobación visual de la señalización del trazado de las zanjas y estado de arquetas de registro', 'Verificar la fijación de los soportes, bandejas y limpieza o deterioro de los mismos', 'Comprobar en las zonas visibles que el cable no está perforado, rajado ni con daños mecánicos en la cubierta por roces con aristas', 'Se realizará una comprobación visual del estado en el que se encuentra la caja y su correcto sellado. Se comprobará que no ha habido filtraciones del exterior por ninguna junta y que el diseño y ejecución de las conexiones son correctos', 'Se revisará que todas las juntas están correctamente colocadas', 'Se comprobará que no hay tapones sueltos ni otros elementos mal fijados que permitan la entrada de elementos (agua, polvo,…) desde el exterior', 'Se verificará que la caja no esté dañada, sea estanca y no existan indicios de roturas', 'Se comprobará el correcto anclaje y sujeción de la caja', 'Asegurarse de que las cajas quedan convenientemente cerradas y estancas. Ante la duda o presencia de condensaciones en el interior, sustituir la junta de estanqueidad o utilizar cinta selladora especial para asegurar la estanqueidad de las mismas', 'Comprobar la correcta identificación de todos los elementos'], '{"Equipos de seguridad": ["Casco.", "Calzado de seguridad.", "Guantes de trabajo.", "Guantes aislantes."], "Herramientas": ["Procedimientos de trabajo para mantenimiento preventivo en plantas f.v.", "Registros de inspección para mantenimiento preventivo en plantas f.v.", "Documentación técnica de la instalación.", "Plano unifilar y de conexión serie-paralelo de la instalación.", "Juego de herramientas de mano aisladas (juego de destornilladores, juego de llaves", "fijas y de carraca, juego de alicates, tijeras, etc.).", "Transmisores de comunicación."], "Equipos de limpieza y material consumible": ["Tortillería variada.", "Cinta aislante.", "Pintura de galvanizado en frío.", "Cinta selladora.", "Spray o grasa de contacto.", "17"]}'::jsonb) on conflict (numero) do nothing;
insert into public.procedimientos (numero, titulo, objeto, alcance, responsable, condicionantes, pasos, equipo) values ('04', 'REVISIÓN DE LAS CONEXIONES ELÉCTRICAS A CAJAS DE PARALELOS', 'Comprobar que todas las conexiones de las cajas se encuentran en buen estado, su apriete es correcto y la identificación esta visible.', 'Todas las cajas de conexión.', 'Trabajador cualificado.', 'Para realizar esta comprobación, será necesario disponer de un plano de conexionado serie y paralelo del campo FV. Antes de realizar cualquier tipo de operación en las cajas de conexión del campo de continua, será necesario tener la instalación parada con el equipo inversor desconectado de la red y con la seta de emergencia accionada, siguiendo el procedimiento indicado por el fabricante. En el caso de que la instalación disponga de dos secciones (líneas generales de paralelos) con dispositivos de seccionamiento por cada sección, no será necesario parar la instalación tal y como se indica en el párrafo anterior, tan solo será necesario abrir los dispositivos de la sección sobre la cual se vaya a actuar y una vez terminado los trabajos en esta, se reestablecerá y se abrirá el de la segunda línea para continuar con los trabajos. ATENCIÓN: Los cables provenientes de los paneles pueden alcanzar altas tensiones aun a pesar de que haya bajas irradiancias.', ARRAY['Cuando se vaya a realizar cualquier operación en una caja de conexión serie-paralelo, será necesario desconectar todas las fuentes de tensión que entran en la caja, siguiendo para ello el siguiente proceso:', 'actuando', '(series de paneles)', 'Con la instalación parada y con los dispositivos de corte general de AC y DC abiertos, se desconectaran todos los terminales positivo y negativo de las series, actuando sobre los fusibles seccionables de todas las cajas de paralelo de una misma sección (línea general de paralelos). Con esto evitaremos tener tensión C.C en las pletinas principales de paralelos', 'Para aislar por completo la caja de paralelo donde se vaya a actuar, será necesario seccionar la entrada de los polos positivo y negativo que entran de los campos rápidas generadores MULTICONTAC del primer y último panel de cada serie, para quitar tensión en los cables de la serie que entran en la caja paralelos. Nunca desconectar los conectores MULTI-CONTACT con el inversor en marcha dado que pueden destruirse por el arco de tensión que aparecería', 'En primer lugar se comprobará la disposición ordenada del cableado en la caja, así como la distancia correcta a los elementos activos', 'Se verificará el correcto etiquetado de los cables y cajas mediante elementos de larga durabilidad, de forma que exista una perfecta trazabilidad de cables y elementos', 'Comprobar que los cables no presentan deshilamiento, hilos sueltos o exceso de conductor visto (>5 mm)', 'Detectar si hay en los terminales o en los conductores cambios anormales de color', 'Observar si el termorretráctil y las bornas de conexión están intactas y en buen estado', 'conexiones', 'sobre', 'Una vez retiradas todas las posibles fuentes de tensión, se comprobará con un multímetro la ausencia de tensión, y se procederá a realizar el mantenimiento y comprobaciones según las gamas de trabajo', 'Comprobar que los cables están firmemente conectados, los bornes y las punteras de los cables están correctamente introducidas y con el apriete adecuado. Si se observa alguna conexión floja, proceder al apriete correspondiente o volver a realizar la conexión si fuera necesario', 'Revisar que los prensaestopas están convenientemente fijados a las cajas (bien apretados, sin holguras y no giran sobre si mismos). Si se observa alguno flojo proceder al apriete correspondiente', 'Asegurarse de que los terminales están libres de corrosión y las conexiones son eléctricamente eficaces. En ambientes especialmente adversos, proteger las conexiones con algún protector contra la corrosión (spray, grasa, etc.)', 'Comprobar la correcta conexión a tierra de masas metálicas y de protección, comprobando que la conexión de protección está separada de la tierra de masas metálicas', 'Verificar el correcto apriete de los elementos al embarrado', 'Revisar el descargador de sobretensiones para que esté en correcto estado y si algún cartucho está fundido debe cambiarse inmediatamente', 'Supervisar el correcto estado de toda la aparamenta del cuadro', 'Terminada la revisión de las cajas de conexión, se volverán a conectar todos los dispositivos MULTI-CONTAC y se cerraran todos fusibles seccionables de las cajas generales de paralelo. A la hora de realizar estos trabajos, existe peligro de contacto eléctrico indirecto, por lo que es necesaria la utilización de herramienta aislada clase', 'Comprobación de la resistencia de aislamiento (megado) si procede según el procedimiento 8', 'Ensayo de tensión aplicada (rigidez dieléctrica) si procede'], '{"Aparatos de medida": ["Cámara termográfica.", "Termómetro láser."], "Equipos de seguridad": ["Casco.", "Calzado de seguridad.", "Guantes de trabajo.", "Guantes aislantes."], "Herramientas": ["Procedimientos de trabajo para mantenimiento preventivo en plantas f.v.", "Registros de inspección para mantenimiento preventivo en plantas f.v.", "Documentación técnica de la instalación.", "Plano unifilar y de conexión serie-paralelo de la instalación.", "Juego de herramientas de mano aisladas (juego de destornilladores, juego de llaves", "fijas y de carraca, juego de alicates, tijeras, etc.).", "Prensa-terminales.", "Pinza amperimétrica para corriente continua y alterna.", "Llaves dinamométricas desde 8Nm hasta 200Nm.", "Transmisores de comunicación.", "Llave maestra para apertura de armarios eléctricos.", "19"]}'::jsonb) on conflict (numero) do nothing;
insert into public.procedimientos (numero, titulo, objeto, alcance, responsable, condicionantes, pasos, equipo) values ('05', 'INSPECCIÓN DE LOS MÓDULOS FOTOVOTAICOS', 'El objetivo de esta comprobación es detectar cualquier defecto visual de la parte frontal, posterior, bastidor y caja de conexión del módulo fotovoltaico. Se comprobarán efectos conocidos en los paneles como Browning o yellowing o fractales o defectos en la superficie de las células con los llamados “redes neuronales” en partes delanteras y revisar efecto de Browning o yellowing en las partes traseras de los módulos fotovoltaicos.', 'Todos los módulos de la instalación fotovoltaica.', 'Trabajador cualificado.', 'Deberá realizarse bajo condiciones de alta luminosidad y radiación. 22', ARRAY['La inspección visual constará de los siguientes puntos:', 'Inspección visual del frontal del Módulo:', 'Inclusiones metálicas en el laminado', 'Inclusiones en el cristal', 'Células rotas', 'Células en contacto entre sí', 'Células semitapadas por el bastidor', 'Alineamiento de la cinta de cobre sobre la malla de serigrafía', 'Aspecto visual de la soldadura', 'Sellado del bastidor y el cristal', 'Arañazos, burbujas o desperfectos en el cristal', 'Burbujas generadas en el proceso de laminación', 'Defectos visuales (como Browning o yellowing o fractales o defectos en la superficie de las células con los llamados “redes neuronales”)', 'Inspección visual de la zona posterior del Módulo:', 'Sujeción de la caja de conexiones', 'Sellado del bastidor', 'Arañazos o cortes en el tedlar o poliéster', 'Indicios de reproceso o reparaciones', 'Defectos visuales (como efecto de Browning o yellowing en las partes traseras de los módulos fotovoltaicos)', 'Inspección del bastidor:', 'Bajo espesor de anodizado en el Aluminio', 'Arañazos en el bastidor', 'Falta de apriete en los tornillos o sistemas de fijación', 'Deformaciones en el marco', 'Identificación de la toma de tierra', 'Inspección de la caja de conexiones:', 'Falta de apriete de los diodos', 'Verificación del funcionamiento de los diodos', 'Falta de apriete en los cables de conexión', 'Longitud de los cables', 'Correcto estado de total estanqueidad, verificando la correcta colocación de la tapa y la inexistencia de roturas', 'Incumplimiento de especificación (requisito UV, sección conductores,…)', 'Verificación de polaridad', 'Estado físico', 'Falta de aislamiento en elementos en tensión', 'Posibilidad de cortocircuitos en trenzas de salida del módulo', 'Sellado interno de la caja', 'Cierre de la tapa'], '{"Aparatos de medida": ["Termómetro.", "Cámara de fotos."], "Equipos de seguridad": ["Casco.", "Calzado de seguridad.", "Guantes de trabajo.", "Guantes aislantes.", "Chaleco reflectante."], "Herramientas": ["Documentación técnica de la instalación.", "Plano unifilar y de conexión serie-paralelo de la instalación."]}'::jsonb) on conflict (numero) do nothing;
insert into public.procedimientos (numero, titulo, objeto, alcance, responsable, condicionantes, pasos, equipo) values ('06', 'MEDIDA DE TENSIÓN DE STRINGS EN CIRCUITO ABIERTO', 'El objeto de este procedimiento es indicar los pasos a seguir para realizar la medida de tensión de strings en circuito abierto.', 'Medicion aleatoria de los strings de paneles instalados de cada una de las potencias', 'Trabajador cualificado.', 'Este procedimiento se procurará realizar en días soleados y sin nubes, con radiación superior a 500 W/m2.', ARRAY['El proceso a seguir para realizar estas mediciones será el siguiente:', 'Desconectar los terminales positivo y negativo, actuando sobre los elementos de protección y desconexión correspondientes a la serie a comprobar', 'Preparar el polímetro para medir tensiones DC y seleccionar la escala adecuada comprobando la tensión de circuito abierto en las características técnicas de un panel y multiplicándola por el número de paneles que configuren la serie', 'Colocar las sondas del polímetro en los terminales de los cables positivo y negativo que entran del circuito generador (serie de paneles) en la caja paralelos. La inversión de polaridad provocará (simplemente) una lectura negativa', 'Para verificar que la tensión Vo existente entre los terminales positivo y negativo de cada circuito generador (string), es la correcta para las condiciones de trabajo de los paneles en el momento de realizar la medida, hay que tener en cuenta que las medidas obtenidas están fuertemente influenciada por la temperatura de las células de los módulos F.V en el momento de realizarla, se toma como referente que la temperatura de las células es del orden de unos 25ºC superior a la Tª ambiente'], '{"Aparatos de medida": ["Multímetro", "Piranómetro.", "Termómetro."], "Equipos de seguridad": ["Casco.", "Calzado de seguridad.", "Guantes de trabajo.", "Guantes aislantes."], "Herramientas": ["Procedimientos de trabajo para mantenimiento preventivo en plantas F.V.", "Registros de inspección para mantenimiento preventivo en plantas F.V.", "Documentación técnica de los paneles fotovoltaicos.", "Plano unifilar y de conexión serie-paralelo de la instalación.", "Juego de herramientas de mano aisladas (juego de destornilladores, juego de llaves", "fijas y de carraca, juego de alicates, tijeras, etc.).", "Transmisores de comunicación.", "Llave maestra para apertura de armarios eléctricos.", "25"]}'::jsonb) on conflict (numero) do nothing;
insert into public.procedimientos (numero, titulo, objeto, alcance, responsable, condicionantes, pasos, equipo) values ('07', 'MEDIDA DE CURVAS V-I DE PANELES F.V', 'El objeto de este procedimiento es verificar la curva de potencia V-I de los strings y comprobar que se corresponden con las que garantiza el fabricante de los paneles.', 'Medición aleatoria de los strings de paneles instalados de cada una de las potencias', 'Trabajador cualificado.', 'Para la realización de estos trabajos será necesario disponer de los flashreport de los paneles a ensayar, así como los esquemas unifilares del campo de continua.', ARRAY['Se extraerán los fusibles de la caja de conexión de los strings a medir, y una vez abierto el string, se conectan los terminales positivo y negativo del equipo de medida en las bornas de entrada a la caja respetando la polaridad de la serie', 'Una vez conectado, se toman varias medidas de temperatura en varios de los paneles a medir con la sonda de temperatura y posteriormente se deja el equipo Data logger registrando irradiación mientras se están realizando las medidas de V-I', 'Con el equipo de medida de curvas conectado y el equipo data logger registrando valores de irradiancia, se toma la medida de tensión en circuito abierto (Vo) de la serie y a continuación la intensidad de cortocircuito (Icc) y por último se saca la curva de potencia V- I de la serie, quedando guardada en la memoria del equipo para su posterior estudio', 'Se considerará la prueba aceptada, si al extrapolar las curvas tomadas por el equipo en condiciones Standard y compararlas estas con los datos de potencia en condiciones Standard de cada una de las series, se observa que los resultados obtenidos se corresponden con los datos teóricos para el modelo de panel instalado'], '{"Aparatos de medida": ["Sonda o termopar conectada a data logger.", "Medidor de irradiancia de precisión 3% o superior.", "Data logger.", "Equipo de medida de curvas V-I."], "Equipos de seguridad": ["Casco.", "Calzado de seguridad.", "Guantes de trabajo.", "Guantes aislantes."], "Herramientas": ["Procedimientos de trabajo para mantenimiento preventivo en plantas F.V.", "Registros de inspección para mantenimiento preventivo en plantas F.V.", "Documentación técnica de los paneles fotovoltaicos.", "Plano unifilar y de conexión serie-paralelo de la instalación.", "Juego de herramientas de mano aisladas (destornilladores, llaves, alicates,…).", "Pinza amperimétrica para corriente continua y alterna.", "Multímetro 1000 V.", "Transmisores de comunicación.", "Llave maestra para apertura de armarios eléctricos.", "27"]}'::jsonb) on conflict (numero) do nothing;
insert into public.procedimientos (numero, titulo, objeto, alcance, responsable, condicionantes, pasos, equipo) values ('08', 'MEDIDA DE AISLAMIENTO EN EL CABLEADO DE CC', 'El objeto de esta prueba es comprobar el estado en que se encuentra el aislamiento del cable de BT en la parte de corriente continua.', 'Medición aleatoria del cable de BT de corriente continua.', 'Trabajador cualificado.', 'Para realizar estos ensayos será necesario que el tramo de cableado a ensayar se encuentre fuera de servicio y puesto en descargo. 29', ARRAY['De manera previa se realizará una inspección visual de todo el cableado accesible chequeando su correcto estado y la ausencia de empalmes o reparaciones realizados con cinta aislante u otro elemento no adecuado', 'El cableado que discurra por bandeja se inspeccionará visualmente. En el caso en el que se observasen ralladuras, cortes o cualquier otro tipo de daño, éstos serán sustituidos', 'Las tensiones de prueba para medidas de resistencia de aislamiento general estarán comprendidas entre 500 V y 1000 V, según se especifique en cada caso', 'A menos que se indique lo contrario, la duración mínima de la prueba será durante el tiempo necesario para la estabilización de la medida, no siendo nunca inferior a 1 minuto. El medidor, debe estar en posición horizontal durante el tiempo que dure la medición', 'En los casos en que sea posible, se utilizará la borna de guarda del aparato para evitar corrientes de fuga ficticias y eliminar de la medida el aislamiento asociado con ciertos terminales del circuito ensayado', 'El modo en que deben efectuarse las pruebas de aislamiento en cables viene', 'determinada por el tipo de cable de que se trate:', 'Para conductores unipolares apantallados la prueba se efectuará entre el conductor y la pantalla puesta a tierra', 'Para cables multipolares con pantallas individuales para cada conductor, las pruebas se harán entre cada conductor y su correspondiente pantalla', 'En el caso de cables multipolares sin pantallas individuales pero con protección metálica exterior, las pruebas se realizarán generalmente entre cada conductor y todos los demás unidos a la protección de puesta a tierra. Esto también aplica a cables multipolares con pantalla exterior. Cuando sea necesario probar separadamente el aislamiento entre los diversos conductores y entre cada uno de ellos y la protección o pantalla puesta a tierra se utilizará la borna de guarda para conectar a ella los demás conductores'], '{"Aparatos de medida": ["Medidor de aislamiento 1000Vac."], "Equipos de seguridad": ["Casco.", "Calzado de seguridad.", "Guantes de trabajo.", "Guantes aislantes."], "Herramientas": ["Procedimientos de trabajo para mantenimiento preventivo en plantas f.v.", "Registros de inspección para mantenimiento preventivo en plantas f.v.", "Documentación técnica de la instalación.", "Plano unifilar y de conexión serie-paralelo de la instalación.", "Juego de herramientas de mano aisladas (juego de destornilladores, juego de llaves", "fijas y de carraca, juego de alicates, tijeras, etc).", "Transmisores de comunicación.", "Llave maestra para apertura de armarios eléctricos."]}'::jsonb) on conflict (numero) do nothing;
insert into public.procedimientos (numero, titulo, objeto, alcance, responsable, condicionantes, pasos, equipo) values ('09', 'MEDIDA DE LA RESISTENCIA A TIERRA EN CAMPO FOTOVOLTAICO', 'El objeto de esta prueba es medir la resistencia de la red de tierras en el campo fotovoltaico.', 'Medición aleatoria de la instalación fotovoltaica y de servicios auxiliares.', 'Trabajador cualificado.', 'Red de tierra totalmente instalada en el campo fotovoltaico. 31', ARRAY['De manera previa se realizará una inspección visual de todo el cableado accesible chequeando su correcto estado y la ausencia de empalmes o reparaciones realizados con cinta aislante u otro elemento no adecuado', 'Se asegurará que todos los elementos, incluidos los tramos de bandeja de cables, están conectados al cable de tierra mediante algún tipo de presilla o terminal adecuado', 'Para medir la resistencia a tierra el telurómetro se conecta a la red de tierra que se quiere medir. Se conectan 2 picas de tierra; una, a una distancia de 10 metros del telurómetro, y otra a 10 metros de la primera. Se pone en funcionamiento el telurómetro y se visualiza la medida'], '{"Aparatos de medida": ["Telurómetro."], "Equipos de seguridad": ["Casco.", "Calzado de seguridad.", "Guantes de trabajo.", "Guantes aislantes."], "Herramientas": ["Procedimientos de trabajo para mantenimiento preventivo en plantas f.v.", "Registros de inspección para mantenimiento preventivo en plantas f.v.", "Documentación técnica de la instalación.", "Plano de red de tierras.", "Juego de herramientas de mano aisladas (juego de destornilladores, juego de llaves", "fijas y de carraca, juego de alicates, tijeras, etc).", "Transmisores de comunicación."]}'::jsonb) on conflict (numero) do nothing;
insert into public.procedimientos (numero, titulo, objeto, alcance, responsable, condicionantes, pasos, equipo) values ('10', 'ESTUDIO TERMOGRÁFICO DE PUNTOS CALIENTES EN PANELES', 'El objeto de esta prueba es detectar posibles puntos calientes en los módulos fotovoltaicos.', '100% de los módulos de la central fotovoltaica.', 'Trabajador cualificado.', 'La central fotovoltaica estará en funcionamiento con los paneles conectados a los cuadros de CC. Se elegirá un día soleado y sin nubes. Para realizar esta medida, la radiación deber ser superior a 700 w/m2.', ARRAY['Antes de realizar la inspección se comprobará que la cámara está en fecha y hora local', 'Inicialmente se llevará a cabo la inspección termográfica de todos los módulos y el análisis termográfico solamente de aquellos que cumplan las condiciones que se mencionan a continuación', 'a) Inspección termográfica:', 'Enfocar con la cámara termográfica cada módulo para buscar gradiente térmicos', '(diferencias de temperatura) mayores de 10ºC', 'De presentar dicha diferencia térmica, hay que comprobar las siguientes situaciones:', 'o Existencia de suciedad incrustada sobre el módulo (barro, excrementos,…) o Existencia de elementos que hagan sombra en el módulo (vegetación, líneas', 'aéreas,…)', 'o Existencia de cambio de color en las células o alrededor de ellas (amarillamiento', 'de la célula)', 'b) Análisis termográfico:', 'De los módulos que presenten incrementos de temperatura significativos, se ubicará e identificará correctamente, realizándose y guardándose las termografías de dichos módulos', 'Hay que registrar en el correspondiente PPI, la fecha y hora, la irradiancia y temperatura de la célula equivalente en el momento en el que se realizó la termografía'], '{"Aparatos de medida": ["Cámara termográfica.", "Pinza amperimétrica DC.", "Piranómetro.", "Termómetro."], "Equipos de seguridad": ["Arnés de seguridad.", "Casco.", "Calzado de seguridad.", "Guantes de trabajo.", "Chaleco reflectante."], "Herramientas": ["Procedimientos de trabajo para mantenimiento preventivo en plantas f.v.", "Registros de inspección para mantenimiento preventivo en plantas f.v.", "Documentación técnica de la instalación.", "33"]}'::jsonb) on conflict (numero) do nothing;
insert into public.procedimientos (numero, titulo, objeto, alcance, responsable, condicionantes, pasos, equipo) values ('11', 'ESTUDIO TERMOGRÁFICO DE PUNTOS CALIENTES ELÉCTRICOS', 'El objeto de esta prueba es detectar puntos calientes en conexiones de los cuadros de CC y CA así como en todos los elementos (inversores incluidos) pertenecientes a la instalación que contengan conexiones eléctricas.', 'Este procedimiento se realizará al 100% de los cuadros eléctricos.', 'Trabajador cualificado.', 'La central fotovoltaica estará en funcionamiento con los paneles conectados a los cuadros de CC. La inspección termográfica se realizará en días soleados y con unas condiciones mínimas de radiación de 700 W/m2 sobre el plano inclinado, con el fin de asegurar un funcionamiento de los equipos en condiciones de producción óptima.', ARRAY['Se realizará inspección termográfica a las conexiones de los cuadros de CC y CA, inversores, transformadores y a las conexiones y dispositivos a analizar para detectar puntos con altas temperaturas debido a golpes, tensiones, malas conexiones,…', 'Antes de realizar la inspección se comprobará que la cámara está en fecha y hora local', 'Inicialmente se llevará acabo la inspección termográfica de todos los módulos y el análisis termográfico solamente de aquellos que cumplan las condiciones que se mencionan a continuación', 'La metodología empleada es la siguiente:', '1. Inspección termográfica de todos los equipos instalados y las conexiones realizadas', '2. Se realizarán y guardarán termografías de todos los equipos instalados y las conexiones realizadas que presenten gradientes de temperaturas significativos', '3. Recogida de datos de radiación y temperatura ambiente de la estación meteorológica. 4. temperatura en el momento en el que se realizó la termografía', 'Hay que registrar en el correspondiente PPI, la fecha y hora, la irradiancia y'], '{"Aparatos de medida": ["Cámara termográfica.", "Pinza amperimétrica AC y DC.", "Piranómetro.", "Termómetro."], "Equipos de seguridad": ["Casco.", "Calzado de seguridad.", "Guantes de trabajo.", "Chaleco reflectante."], "Herramientas": ["Procedimientos de trabajo para mantenimiento preventivo en plantas f.v.", "Registros de inspección para mantenimiento preventivo en plantas f.v.", "Documentación técnica de la instalación.", "35"]}'::jsonb) on conflict (numero) do nothing;
insert into public.procedimientos (numero, titulo, objeto, alcance, responsable, condicionantes, pasos, equipo) values ('12', 'REVISIÓN DEL EQUIPO INVERSOR', 'El objeto de esta revisión es comprobar que el equipo inversor se encuentra en condiciones de funcionamiento y que las conexiones se encuentran en buen estado.', 'Todos los inversores.', 'Trabajador cualificado.', 'Antes de realizar cualquier intervención en el interior de un equipo inversor, será necesario seguir las instrucciones del manual de operación y mantenimiento del fabricante y siempre habrá que tomar las siguientes precauciones: • Apagar el equipo mediante la tecla de marcha/paro si fuera posible. • Aplicar la seta de emergencia si dispone de ella. • Una vez que el equipo no se encuentre inyectando, deberá ser cortado el circuito que llega desde paneles actuando sobre el seccionador, automático ó elemento de corte que permita que la tensión continua no llegue al equipo mientras que estemos trabajando sobre él. • Una vez realizado el paso anterior, el siguiente será cortar la tensión de alterna actuando sobre el interruptor general y/o diferencial presentes en la instalación. Las operaciones a realizar dentro del inversor deben ser realizadas con precaución, debido a que existe peligro de descargas eléctricas a pesar de haber desconectado el inversor de la red y de los paneles. Por tanto es conveniente antes de realizar cualquier intervención en los equipos inversores o cajas de conexión, asegurarse que el inversor está desconectado de la red alterna y de la continua de los paneles durante, al menos, 30 minutos para dejar que se descarguen los condensadores del equipo o utilizar una resistencia de descarga del calibre adecuado según croquis, para realizar la descarga inmediata antes de la intervención. • Transcurrido este tiempo, se comprobará ausencia de tensión tanto en alterna como en continua y se procederá a realizar el mantenimiento y comprobaciones según especificación del fabricante del equipo.', ARRAY['Comprobar mediante pequeños tirones que los cables están firmemente conectados. Si se observa algún aflojamiento, proceder al apriete correspondiente o volver a realizar la conexión', 'Si hay prensaestopas, comprobar que estos están convenientemente fijados al aparato (bien apretados y sin holguras, no giran sobre sí mismos). Si se observa algún aflojamiento, proceder al apriete correspondiente', 'Comprobar que la longitud de los cables en el interior del aparato es la adecuada para que las conexiones no se vean sometidas a esfuerzos', 'Asegurarse de que los terminales están libres de corrosión y las conexiones son eléctricamente eficaces. En ambientes especialmente adversos, proteger las conexiones con algún protector contra la corrosión (spray, grasa, etc.)', 'Comprobación del estado de la envolvente metálica: faltas de pintura, oxidaciones, abolladuras, cerraduras dañadas, etc', 'Verificación de los puntos de sujeción y conexión, tortillería y anclajes, reapretando si fuese necesario según indicaciones del fabricante', 'Revisar el funcionamiento de los motores de refrigeración', 'Comprobar que el aparato no muestra restos de suciedad que dificulte la visualización de sus indicaciones o pueda afectar a su funcionamiento. En su caso, eliminar la suciedad con un paño humedecido en agua o limpiador multiusos', 'Asegurarse mediante inspección visual y pequeñas sobrecargas de peso que la sujeción del aparato es firme y que la superficie de sustentación del mismo no muestra signos de deterioro (grietas, desprendimientos de material, etc.). En su caso, proceder con la obra civil necesaria para asegurar la reparación del estado de deterioro correspondiente', 'Comprobación de fusibles, descargadores, relés auxiliares y lámparas de señalización. Hay que observar si los pilotos indicadores de fusibles, relés y descargadores de sobretensión han cambiado de color, sustituyendo los cartuchos que fueran necesarios', 'Verificación de enclavamientos y circuitos de mando', 'Revisión del estado de los cables y conexiones', 'Hay que tener especial cuidado con el radiador ubicado en la parte de potencia del inversor puede alcanzar temperaturas elevadas'], '{"Aparatos de medida": ["Cámara termográfica.", "Termómetro láser."], "Equipos de seguridad": ["Casco.", "Calzado de seguridad.", "Guantes de trabajo.", "Guantes aislantes."], "Herramientas": ["Manual de usuario del equipo inversor.", "Procedimientos de trabajo para mantenimiento preventivo en plantas f.v.", "Registros de inspección para mantenimiento preventivo en plantas f.v.", "Documentación técnica de la instalación.", "Plano unifilar y de conexión de la instalación.", "Juego de herramientas de mano aisladas (juego de destornilladores, juego de llaves", "fijas y de carraca, juego de alicates, tijeras, etc).", "Prensa-terminales.", "Pinza amperimetrica para corriente continua y alterna.", "Llaves dinamométricas desde 8Nm hasta 200Nm.", "Transmisores de comunicación.", "Llave maestra para apertura de armarios eléctricos.", "37"], "Equipos de limpieza y material consumible": ["Tortillería variada.", "Cinta aislante.", "Pintura de galvanizado en frío.", "Protección contra corrosión. (Tectyl 120 CGW o similar)", "Cinta selladora.", "Spray o grasa de contacto.", "Bridas de plástico."]}'::jsonb) on conflict (numero) do nothing;
insert into public.procedimientos (numero, titulo, objeto, alcance, responsable, condicionantes, pasos, equipo) values ('13', 'COMPROBACIÓN DEL FUNCIONAMIENTO DEL INVERSOR', 'El objeto de esta prueba es visualizar todos los parámetros de funcionamiento del Inversor.', '100% de los inversores de la instalación fotovoltaica.', 'Trabajador cualificado.', 'Central fotovoltaica en funcionamiento. Se elegirá un día soleado y sin nubes.', ARRAY['Se considerará que el equipo funciona correctamente siempre que se den los siguientes estados:', 'ESTADO 1: Si la tensión de paneles es insuficiente (ver especificaciones del equipo), el equipo se encuentre con el display apagado', 'ESTADO 2: Existiendo tensión de paneles suficiente (ver especificaciones del equipo) para el encendido del display pero no para el arranque. En este estado el equipo permitirá acceder a visualizar todos los parámetros de menú pulsando la tecla correspondiente dependiendo del modelo de equipo inversor, pero no arrancará aunque sea pulsada la tecla de marcha/paro', 'ESTADO 3: Existiendo tensión de paneles suficiente para el arranque (ver especificaciones del equipo), el equipo puede estar generando intensidad. Si el equipo está generando intensidad, por display se mostrará la tensión de continua a la que está trabajando el equipo y la potencia que está generando. En este punto el equipo tiene accesible el menú y podrán verse los distintos parámetros que valora el equipo en funcionamiento. Ucc (Tensión de continua), Pac (Potencia generada), Uac (Tensión alterna a la que está trabajando), Iac (Intensidad generada), Fred (Frecuencia de la tensión alterna a la que trabaja), Pcc (potencia absorbida de los paneles e Icc (Corriente absorbida de paneles)', 'Se considera que el equipo funciona INCORRECTAMENTE estando en el siguiente estado:', 'ESTADO 4: en este estado se pueden dar los siguientes casos:', '1º- El display se encuentra apagado', '2º- El display se encuentra encendido pero no marca ningún tipo de mensaje', '3º- El display se encuentra encendido y marca letras incoherentes por display', '4º- El display se encuentra encendido y marca un mensaje de alarma', 'Para comprobar la fiabilidad de las medidas indicadas por display, se comprobará con ayuda de un voltímetro AC-DC y una pinza amperimétrica AC-DC (o un analizador de redes) las siguientes variables durante una hora con mediciones cada 30 segundos:', 'Tensión entrada CC', 'Intensidad entrada CC', 'Potencia entrada CC', 'Tensión salida AC', 'Intensidad salida AC', 'Coseno de phi', 'Potencia de salida AC', 'Energía acumulada salida', 'Temperatura', 'Rendimiento inversor', 'Se comprobará que se cumplen las especificaciones del inversor permitiendo un margen de error en la medida de un 2%'], '{"Aparatos de medida": ["Multímetro.", "Pinza amperimétrica AC y DC.", "Piranómetro.", "Termómetro."], "Equipos de seguridad": ["Casco.", "Calzado de seguridad.", "Guantes de trabajo.", "Guantes aislantes.", "Chaleco reflectante."], "Herramientas": ["Manual de usuario de los equipos inversores.", "Procedimientos de trabajo para mantenimiento preventivo en plantas f.v.", "Registros de inspección para mantenimiento preventivo en plantas f.v.", "Documentación técnica de la instalación.", "Juego de herramientas de mano aisladas (juego de destornilladores, juego de llaves", "fijas y de carraca, juego de alicates, tijeras, etc).", "Transmisores de comunicación.", "Llave maestra para apertura de armarios eléctricos.", "40"]}'::jsonb) on conflict (numero) do nothing;
insert into public.procedimientos (numero, titulo, objeto, alcance, responsable, condicionantes, pasos, equipo) values ('14', 'COMPROBACIÓN DEL FUNCIONAMIENTO DE LOS CONTADORES DE ENERGÍA', 'El objeto de esta prueba es comprobar que los contadores de energía funcionan correctamente.', '100% de los contadores de la central fotovoltaica.', 'Trabajador cualificado.', 'Central fotovoltaica en funcionamiento.', ARRAY['Comprobar el estado de la envolvente detectando problemas en la estanqueidad', 'suciedad, etiquetado del cuadro, roturas, etc', 'Revisar los bornes, punteras y terminales del cuadro, asegurando su correcta', 'conexión y el apriete adecuado', 'Verificar el correcto estado de los fusibles y descargadores, si alguno estuviera', 'dañado o fundido se deber reemplazar inmediatamente', 'Revisar que no hay cables sueltos y que todos transcurren por sus bandejas', 'Comprobar el correcto estado de', 'interruptores magnetotérmicos, relés', 'diferenciales y toroidales', 'Realizar una supervisión termográfica del cuadro para comprobar que no hay equipos', 'con puntos calientes', 'Navegar por todas las funciones del contador comprobando que no dan problemas y chequear que la producción de energía (Kwh.) coincide con la acumulada y la instantánea del inversor restando las pérdidas'], '{"Aparatos de medida": ["Multímetro.", "Pinzas amperimétricas AC."], "Equipos de seguridad": ["Casco.", "Calzado de seguridad.", "Guantes de trabajo.", "Guantes aislantes.", "Chaleco reflectante."], "Herramientas": ["Manual de usuario de los equipos contadores.", "Procedimientos de trabajo para mantenimiento preventivo en plantas f.v.", "Registros de inspección para mantenimiento preventivo en plantas f.v.", "Juego de herramientas de mano aisladas (juego de destornilladores, juego de llaves", "fijas y de carraca, juego de alicates, tijeras, etc).", "43"]}'::jsonb) on conflict (numero) do nothing;
insert into public.procedimientos (numero, titulo, objeto, alcance, responsable, condicionantes, pasos, equipo) values ('15', 'COMPROBACIÓN DEL DISPARO DE LAS PROTECCIONES DIFERENCIALES', 'El objeto de esta prueba es comprobar el tiempo e intensidad de disparo de los diferenciales.', '100% de interruptores diferenciales de la instalación fotovoltaica.', 'Trabajador cualificado.', 'Para realizar esta prueba será necesario que la instalación se encuentre parada y con alimentación.', ARRAY['Se provoca el disparo de la protección diferencial con el comprobador multifunción y', 'se visualiza el tiempo de disparo y la intensidad de disparo', 'Se deberán cumplir las especificaciones del fabricante de la protección diferencial. La protección deberá estar tarada en los valores adecuados para garantizar la seguridad de la instalación, según cálculos de proyecto y usos habituales', 'Se verificará además de su correcto funcionamiento el estado de las protecciones, que', 'no deben presentar daños, degradación, etc'], '{"Aparatos de medida": ["Comprobador multifunción."], "Equipos de seguridad": ["Casco.", "Calzado de seguridad.", "Guantes de trabajo.", "Guantes aislantes.", "Discos de peligro.", "Chaleco reflectante."], "Herramientas": ["Procedimientos de trabajo para mantenimiento preventivo en plantas f.v.", "Registros de inspección para mantenimiento preventivo en plantas f.v.", "Documentación técnica de la instalación.", "Juego de herramientas de mano aisladas (juego de destornilladores, juego de llaves", "fijas y de carraca, juego de alicates, tijeras, etc).", "Transmisores de comunicación.", "45"]}'::jsonb) on conflict (numero) do nothing;
insert into public.procedimientos (numero, titulo, objeto, alcance, responsable, condicionantes, pasos, equipo) values ('16', 'REVISIÓN DEL TRANSFORMADOR DE POTENCIA', 'El objeto de este procedimiento es establecer las pautas a seguir para comprobar el estado del transformador de potencia.', 'Todos los transformadores de la instalación.', 'Trabajador cualificado para trabajos en M.T.', 'Para la realización de estos trabajos será necesario poner el transformador en descargo.', ARRAY['1. LIMPIEZA DEL TRANSFORMADOR', 'No se puede utilizar ningún tipo de disolvente o desengrasante para la limpieza del equipo ni tampoco se puede verter agua directamente sobre él', 'Para la limpieza se utilizará el cepillo de cerdas blandas y trapos como decapante de la suciedad', 'En el caso de que la suciedad adherida no se desprenda, se admite frotarla con un trapo ligeramente humedecido en agua, retirando después la humedad de la zona con un trapo seco. Se comprobará que no hay daños, ruidos anómalos, vibraciones, puntos de oxidación, etc', '2. COMPROBACIÓN DE CONEXIONES ELECTRICAS', 'No se comprobará el par de apriete de aquellos tornillos y tuercas que estén lacrados o marcados y mantengan su posición original. Se lacrarán o marcarán en AMARILLO todos aquellos tornillos o tuercas sin marca de fábrica, tras la comprobación de su par de apriete', 'Cable de MT: Se verificará el par de todos los terminales, siempre y cuando no estén marcados previamente: Los terminales de MT no se engrasarán nunca', 'Cables de BT: En ambientes polvorientos, corrosivos o salinos se sellará, una vez instalado y fijado el terminal, la unión – borde del terminal cable BT con pletina de aluminio de los fusibles, con silicona LOCTITE® 5970', 'En caso de que sea necesario desmontar alguno de los terminales, se lijarán las caras de las pletinas con un abrasivo de grado fino, retirando el polvo con un trapo limpio. Se lijará suavemente el terminal del cable hasta que el estaño recupere su brillo', 'Aplicar grasa conductoras en todas las conexiones eléctricas:', 'Conexiones Cobre-Cobre: PENETROX E', 'Conexiones Aluminio-Cobre: PENETROX A-13', 'Curvatura:', 'El radio de curvatura mínimo para los cables debe ser de 5 veces su diámetro exterior', '3. COMPROBACION DE LAS DISTANCIAS ELECTRICAS', 'Comprobación de las distancias de MT: Las distancias desde cualquier parte viva del trafo a masa (incluyendo los cables de BT) deben ser:', 'Trafos hasta 12kV 120mm Trafos hasta 24kV 220mm Trafos hasta 36kV 320mm', 'Comprobación de las distancias de BT: Comprobar que las distancias que se indican a continuación son de al menos 50mm', '4. COMPROBACION DE LAS SONDAS DE TEMPERATURA', 'Revisar el cableado y conexión de las sondas de temperatura', 'Comprobar las sondas de temperatura midiendo el valor de la señal del termómetro y verificar que este valor se corresponde con la temperatura del trafo', 'Asegurar la correcta regulación de los disparos del termostato', '5. VARIOS', 'Además de los puntos a revisar según registro, se harán las siguientes comprobaciones:', 'Estanqueidad de la cuba del transformador, descartando pérdidas de aceite por juntas de bornas, juntas de tapas, etc', 'Nivel de aceite aislante en visor de nivel', 'Coloración de silicagel, sustituyéndolo si fuese necesario', 'Pruebas de funcionamiento de las protecciones del transformador (Buchholz, termómetro, termostato, etc.) comprobando la actuación de las mismas y generación de alarmas', 'Pruebas de aislamiento', 'Pruebas de rigidez dieléctrica del aceite y toma de muestras para ensayo físico- químico si fuese necesario', 'Pruebas de relación de transformación si fuese necesario', 'Estado del cuadro e interruptor del CBT, así como de sus contactos y apriete de la tortillería', 'Estado de los fusibles del CBT', 'Correcto estado y limpieza de los aisladores', 'Puesta a tierra y el estado de las conexiones a la misma', 'Si en alguna de las medidas los valores de aislamiento no se encuentran dentro de los límites, se soltarán las líneas del transformador y se realizará la prueba por separado con el fin de localizar la parte de la instalación donde se encuentra la falta de aislamiento', 'Los bobinados del transformador han de descargarse inmediatamente después de la medida, para impedir posibles descargas eléctricas'], '{"Aparatos de medida": ["Multímetro.", "Sonda P.T 100 de cápsula metálica o dispositivo de comprobación de resistencias", "variables (potenciómetro, bloque de resistencias, etc.).", "Flexómetro.", "Medidor de aislamiento 1000/5000V."], "Equipos de seguridad": ["Casco.", "Calzado de seguridad.", "Guantes de trabajo.", "Guantes aislantes.", "Discos de peligro.", "Equipo de puesta a tierra y descargo.", "Pértigas detectoras de tensión.", "Pértiga aislante de maniobra.", "Chaleco reflectante"], "Herramientas": ["Manual de usuario del transformador.", "Procedimientos de trabajo para mantenimiento preventivo en plantas f.v.", "Registros de inspección para mantenimiento preventivo en plantas f.v.", "Documentación técnica de la instalación.", "Plano unifilar y de conexión de la instalación de M.T.", "Juego de herramientas de mano aisladas (juego de destornilladores, juego de llaves", "47", "fijas y de carraca, juego de alicates, tijeras, etc).", "Aspirador.", "Linterna.", "Prensa-terminales.", "Escalera.", "Llaves dinamométricas desde 8Nm hasta 200Nm.", "Transmisores de comunicación.", "Llave maestra para apertura de armarios eléctricos."], "Equipos de limpieza y material consumible": ["Papel y trapos de limpieza.", "Guantes de látex.", "Tortillería variada.", "Cinta aislante.", "Pintura esmalte.", "Pintura de galvanizado en frío.", "Protección contra corrosión. (Tectyl 120 CGW o similar)", "Cinta selladora.", "Limpiador multiusos.", "Spray o grasa de contacto.", "Bridas de plástico.", "Cepillo de cerdas de plástico blandas (300mm).", "Brocha de pintura mediana (70mm).", "Liquido limpiador dieléctrico.", "Grasa de contacto eléctrico (molikote, Penetrox A13 o similar)."]}'::jsonb) on conflict (numero) do nothing;
insert into public.procedimientos (numero, titulo, objeto, alcance, responsable, condicionantes, pasos, equipo) values ('17', 'COMPROBACION DEL ESTADO DEL CABLEADO DE M.T', 'El objeto de esta prueba es comprobar el estado en que se encuentra el cableado de M.T', 'Todo el cableado de MT.', 'Trabajador cualificado para trabajos en M.T.', 'Antes de comenzar con la revisión, se comprobará ausencia de condensación y humedades', ARRAY['Comprobación visual de la señalización del trazado de las zanjas y estado de arquetas de registro', 'Revisar la fijación de los soportes, aisladores y la limpieza o deterioro de los mismos', 'Verificar que el cable no está perforado, rajado ni con daños mecánicos en la cubierta', 'Comprobar el par de apriete de las conexiones con ayuda de una llave dinamométrica según indicaciones del fabricante', 'Supervisar que el cable y las conexiones no han sufrido calentamientos', 'Comprobar el estado de las botellas terminales', 'Verificar la correcta curvatura de los cables', 'Comprobar que las pantallas de los cables de MT están todas puestas a tierra al menos en un extremo del cable', 'Revisar que las fases están identificadas según la secuencia de fases', 'Comprobación de la resistencia de aislamiento (megado)'], '{"Aparatos de medida": ["Medidor de aislamiento 10000Vac."], "Equipos de seguridad": ["Casco.", "Calzado de seguridad.", "Guantes de trabajo.", "Guantes aislantes.", "Discos de peligro.", "Chaleco reflectante."], "Herramientas": ["Procedimientos de trabajo para mantenimiento preventivo en plantas f.v.", "Registros de inspección para mantenimiento preventivo en plantas f.v.", "Documentación técnica de la instalación.", "Plano unifilar y de conexión instalación de M.T", "Juego de herramientas de mano aisladas (destornilladores, llaves, alicates…).", "Llave maestra para apertura de armarios eléctricos.", "Aspirador.", "Linterna.", "Escalera.", "Llaves dinamométricas desde 8Nm hasta 200Nm.", "Transmisores de comunicación.", "Llave maestra para apertura de armarios eléctricos."], "Equipos de limpieza y material consumible": ["51", "Papel y trapos de limpieza.", "Guantes de látex.", "Tortillería variada.", "Cinta aislante.", "Pintura esmalte.", "Pintura de galvanizado en frío.", "Protección contra corrosión. (Tectyl 120 CGW o similar)", "Cinta selladora.", "Limpiador multiusos.", "Spray o grasa de contacto.", "Bridas de plástico.", "Cepillo de cerdas de plástico blandas (300mm).", "Brocha de pintura mediana (70mm)."]}'::jsonb) on conflict (numero) do nothing;
insert into public.procedimientos (numero, titulo, objeto, alcance, responsable, condicionantes, pasos, equipo) values ('18', 'REVISIÓN DE LA INFRAESTRUCTURA ELÉCTRICA DE EVACUACIÓN', 'El objeto de esta prueba es comprobar el estado en que se encuentra la infraestructura eléctrica de evacuación.', 'Toda la infraestructura eléctrica de evacuación de M.T.', 'Trabajador cualificado.', 'Antes de comenzar con la revisión, se comprobará ausencia de condensación y humedades.', ARRAY['Se realizará una inspección visual de toda la traza de la infraestructura, prestando atención a la correcta instalación y ejecución de todos los elementos de acuerdo al proyecto', 'En los tramos de cable subterráneo se procederá a hacer una comprobación de los mismos siguiendo el procedimiento 24 “comprobación cableado M.T”', 'En caso de aparecer centros de transformación o seccionamiento se le aplicarán los procedimientos de inspección correspondientes', 'Este procedimiento se realizará de forma que no afecte al normal funcionamiento y producción de la planta'], '{"Aparatos de medida": ["Medidor de aislamiento 10000Vac."], "Equipos de seguridad": ["Casco.", "Calzado de seguridad.", "Guantes de trabajo.", "Guantes aislantes.", "Discos de peligro.", "Chaleco reflectante."], "Herramientas": ["Procedimientos de trabajo para mantenimiento preventivo en plantas f.v.", "Registros de inspección para mantenimiento preventivo en plantas f.v.", "Documentación técnica de la instalación.", "Plano unifilar y de conexión instalación de M.T", "Juego de herramientas de mano aisladas (juego de destornilladores, juego de llaves", "fijas y de carraca, juego de alicates, tijeras, etc).", "Llave maestra para apertura de armarios eléctricos.", "Aspirador.", "Linterna.", "Escalera.", "53", "Equipos de limpieza y material consumible:", "Papel y trapos de limpieza.", "Guantes de látex.", "Tortillería variada.", "Cinta aislante.", "Pintura esmalte.", "Pintura de galvanizado en frío.", "Protección contra corrosión. (Tectyl 120 CGW o similar).", "Cinta selladora.", "Limpiador multiusos.", "Spray o grasa de contacto.", "Bridas de plástico.", "Cepillo de cerdas de plástico blandas (300mm).", "Brocha de pintura mediana (70mm)."]}'::jsonb) on conflict (numero) do nothing;
insert into public.procedimientos (numero, titulo, objeto, alcance, responsable, condicionantes, pasos, equipo) values ('19', 'COMPROBACIÓN DE LAS INFRAESTRUCTURAS DEL SISTEMA DE MONITORIZACIÓN Y CONTROL', 'El objeto de esta prueba es comprobar que las instalaciones y equipos de monitorización de la planta están operativos y se encuentran en buenas condiciones de funcionamiento.', 'Toda la instalación del sistema de monitorización y control de la planta.', 'Personal cualificado.', 'Para realizar esta comprobación, será necesario disponer de un plano de conexionado de control y alimentación de la instalación del sistema de monitorización. La planta debe encontrarse en funcionamiento. Se elegirá un día soleado y sin nubes.', ARRAY['Se revisarán los siguientes puntos:', 'Comprobar mediante inspección visual y pequeñas sobrecargas de peso que la sujeción de los cuadros es firme y que la superficie de sustentación del mismo no muestra signos de deterioro (movimiento del terreno, grietas, etc.). En su caso, proceder con la obra civil necesaria para asegurar la reparación del estado de deterioro correspondiente', 'Verificar mediante pequeños tirones que los cables están firmemente conectados. Si se observa alguna conexión floja, proceder al apriete correspondiente o volver a realizar la conexión si fuera necesario', 'Asegurar que la longitud de los cables en el interior de las cajas es la adecuada para que las conexiones no se vean sometidas a esfuerzos y que todos los elementos están correctamente identificados y se conducen por las bandejas y tubos correspondientes.  Comprobar que los prensaestopas están convenientemente fijados a las cajas (bien apretados, sin holguras y no giran sobre sí mismos). Si se observa alguno flojo proceder al apriete correspondiente', 'Revisar que los terminales están libres de corrosión y las conexiones son eléctricamente eficaces. En ambientes especialmente adversos, proteger las conexiones con algún protector contra la corrosión (spray, grasa, etc.)', 'Verificar que las cajas quedan convenientemente cerradas y estancas. Ante la duda o presencia de condensaciones en el interior, sustituir la junta de estanqueidad o utilizar cinta selladora especial para asegurar la estanqueidad de las mismas. A la hora de realizar estos trabajos existe peligro de contacto eléctrico indirecto, por lo que es necesaria la utilización de herramienta aislada clase', 'Desde el centro de control se comprobará que todos los equipos de la estación meteorológica y todas las instalaciones fotovoltaicas están monitorizadas, así como la fidelidad de los datos y alarmas reflejados en el sistema con la realidad. Para ello se medirá con los equipos adecuados las distintas variables que registra el sistema', 'anotándose valor y hora, para ser comprobadas con los valores almacenados por el sistema', 'Verificar que el sistema registra los datos y alarmas en tiempo real (30 segundos', 'desde su desencadenamiento)', 'Además se hará un mantenimiento de la aplicación de las aplicaciones del sistema SCADA que consistirá en:', 'Semanalmente se verificará el funcionamiento de las aplicaciones del SCADA comprobando que opera correctamente y se resolverán los posibles incidentes detectados por los operadores a lo largo de la semana', 'Mensualmente se llevará a cabo una inspección general para actualizar el sistema y', 'realizar copias de seguridad de las aplicaciones y de las bases de datos', 'Servicio de asistencia al emplazamiento para la resolución de incidencias graves', 'relacionadas con el hardware'], '{"Aparatos de medida": ["Multímetro.", "Pinza amperimétrica AC y DC.", "Medidor de aislamiento 1000Vac.", "Piranómetro.", "Termómetro."], "Equipos de seguridad": ["Casco.", "Calzado de seguridad.", "Guantes de trabajo.", "Guantes aislantes."], "Herramientas": ["Manual de usuario de los equipos de monitorización.", "Procedimientos de trabajo para mantenimiento preventivo en plantas f.v.", "Registros de inspección para mantenimiento preventivo en plantas f.v.", "Documentación técnica de la instalación.", "Plano unifilar del sistema de monitorización.", "Juego de herramientas de mano aisladas (juego de destornilladores, juego de llaves", "fijas y de carraca, juego de alicates, tijeras, etc).", "Linterna.", "Escalera.", "55", "Transmisores de comunicación.", "Llave maestra para apertura de armarios eléctricos."], "Equipos de limpieza y material consumible": ["Cinta aislante.", "Cinta selladora.", "Bridas de plástico."]}'::jsonb) on conflict (numero) do nothing;
insert into public.procedimientos (numero, titulo, objeto, alcance, responsable, condicionantes, pasos, equipo) values ('20', 'COMPROBACIÓN DE LAS INFRAESTRUCTURAS DE LA ESTACIÓN METEOROLÓGICA', 'El objeto de esta revisión es comprobar que las estaciones meteorológicas se encuentran en buen estado de funcionamiento, incluyendo su limpieza semanal.', 'Todas las estaciones meteorológicas.', 'Personal cualificado.', 'Para realizar esta comprobación, será necesario disponer del manual de operación y mantenimiento de la estación meteorológica del fabricante o instalador, así como también disponer de las especificaciones de montaje mecánico de los diferentes dispositivos del sistema.', ARRAY['Se revisaran los siguientes puntos:', 'Se procederá a limpiar semanalmente el equipo', 'Se comprobará el correcto hormigonado e izado de la torre', 'Se verificará la correcta colocación de todos los equipos y el correcto conexionado de los mismos, haciendo especial hincapié en la accesibilidad a todos ellos para el correcto mantenimiento de los mismos', 'Se revisará que los sensores no muestran restos de suciedad u obstáculos que provoquen sombras y pueda afectar a la medida. En su caso, eliminar la suciedad o posibles obstáculos', 'Se comprobará mediante inspección visual y pequeñas sobrecargas de peso que la sujeción de los sensores y que la superficie de sustentación de los mismos no muestran signos de deterioro (movimiento del terreno, grietas, etc.). En su caso, proceder con la obra civil necesaria para asegurar la reparación del estado de deterioro correspondiente', 'Se verificará que las uniones, puntos de sujeción y conexión, tornillería y anclajes de la estructura no muestran signos de holgura o aflojamiento que puedan provocar vibraciones por efecto del viento. En su caso, proceder a dar el par de apriete correspondiente para la métrica del tornillo y según las instrucciones del fabricante', 'Se comprobará mediante inspección visual que los elementos de la estructura no sufren deformaciones (provocadas por los esfuerzos soportados) no especificadas en el análisis estructural efectuado en la fase de diseño', 'Antes de proceder a la revisión de las conexiones eléctricas, con el fin de evitar accidentes y daños en los equipos del sistema, será necesario retirar cualquier fuente de tensión y dejar la instalación desconectada (teniendo especial atención para evitar perder los registros de irradiancia de la planta)', 'Una vez retiradas todas las posibles fuentes de tensión, se comprobará con un multímetro la ausencia de tensión, y se procederá a realizar el mantenimiento y comprobaciones según este procedimiento', 'Se verificará mediante pequeños tirones que los cables están firmemente conectados. Si se observa alguna conexión floja, proceder al apriete correspondiente y volver a realizar la conexión si fuera necesario', 'Se comprobará que la longitud de los cables en el interior de las cajas es la adecuada para que las conexiones no se vean sometidas a esfuerzos', 'Se verificará que los prensaestopas están convenientemente fijados a las cajas (bien apretados, sin holguras y no giran sobre si mismos). Si se observa alguno flojo proceder al apriete correspondiente', 'Se asegurará que los terminales están libres de corrosión y las conexiones son eléctricamente eficaces. En ambientes especialmente adversos, proteger las conexiones con algún protector contra la corrosión (spray, grasa, etc.)', 'Se revisará que las cajas quedan convenientemente cerradas y estancas, sin golpes ni desperfectos como marcas de oxidación. Ante la duda o presencia de condensaciones en el interior, sustituir la junta de estanqueidad o utilizar cinta selladora especial para asegurar la estanqueidad de las mismas', 'Terminada la revisión de las cajas de conexión, se volverán a reestablecer la alimentación y se procederá a continuar con los trabajos de revisión de los distintos equipos de la estación meteorológica', 'Se comprobará el correcto funcionamiento de todos los equipos, así como la fidelidad de los datos. Para ello se medirá con los equipos adecuados las distintas variables que registra el sistema. A la hora de realizar estos trabajos existe peligro de contacto eléctrico indirecto, por lo que es necesaria la utilización de herramienta aislada clase 2', 'Se revisará que el sistema recoge y almacena correctamente todos los datos registrados', 'Se verificará el correcto funcionamiento de la batería', 'Se comprobará que todos los sensores tienen sus respectivos certificados de calibración actualizados', 'Conforme a las instrucciones de los fabricantes, realizar el mantenimiento preventivo específico de cada uno de los equipos'], '{"Aparatos de medida": ["Multímetro.", "Piranómetro.", "Termómetro."], "Equipos de seguridad": ["Arnés de seguridad.", "Casco.", "Calzado de seguridad.", "Guantes de trabajo."], "Herramientas": ["Manual de usuario y mantenimiento de la estación meteorológica y sus distintos", "componentes.", "Procedimientos de trabajo para mantenimiento preventivo en plantas f.v.", "Registros de inspección para mantenimiento preventivo en plantas f.v.", "Documentación técnica de la estación meteorológica.", "P.C portátil.", "Cable serie para comunicaciones.", "Juego de herramientas de mano aisladas (juego de destornilladores, juego de llaves", "fijas y de carraca, juego de alicates, tijeras, etc).", "Escalera.", "Llaves dinamométricas desde 8Nm hasta 200Nm.", "Transmisores de comunicación.", "58", "Llave maestra para apertura de armarios eléctricos."], "Equipos de limpieza y material consumible": ["Papel y trapos de limpieza.", "Guantes de látex.", "Tortillería variada.", "Cinta aislante.", "Pintura de galvanizado en frío.", "Protección contra corrosión. (Tectyl 120 CGW o similar).", "Cinta selladora.", "Spray o grasa de contacto.", "Bridas de plástico.", "Cepillo de cerdas de plástico blandas (300mm)."]}'::jsonb) on conflict (numero) do nothing;
insert into public.procedimientos (numero, titulo, objeto, alcance, responsable, condicionantes, pasos, equipo) values ('21', 'REVISIÓN Y COMPROBACIÓN DE LA INFRAESTRUCTURA ELÉCTRICA DE LOS SERVICIOS AUXILIARES', 'El objeto de esta prueba es verificar que la instalación de servicios auxiliares se encuentra en buen estado de funcionamiento.', '100% de la infraestructura eléctrica de la instalación fotovoltaica.', 'Trabajador cualificado.', 'Para realizar esta comprobación, será necesario disponer de un plano de conexionado de la parte de la instalación de servicios auxiliares.', ARRAY['Comprobar que el cable y las conexiones no han sufrido calentamientos', 'Supervisar la puesta a tierra de todas las partes metálicas', 'Verificar la correcta curvatura de los cables', 'Asegurarse de la correcta fijación de los armarios', 'Comprobar distancias entre conexiones. o Distancias de MT:', 'Las distancias desde cualquier parte viva del trafo a masa (incluyendo los cables de BT) deben ser:', 'Trafos hasta 12kV 120mm Trafos hasta 24kV 220mm Trafos hasta 36kV 320mm', 'o Distancias de BT:', 'Comprobar que las distancias que se indican a continuación son de al menos 50mm', 'Asegurar la correcta identificación de fases', 'Revisar la identificación de las cajas', 'Comprobar la limpieza de los fusibles y de las bases', 'Revisar la presión de las mordazas', 'Cuando sea necesario realizar el reapriete de alguna conexión, se hará con la instalación fuera de servicio y con el interruptor de corte general de AC abierto en la centralización de contadores, además se desconectarán los tres fusibles de cuchilla de la caja BT. Una vez extraídos, se comprobara con un multímetro la parte del portafusibles que se encuentra con tensión, colocando un cartel indicando la presencia de tensión en ese punto y se procederá a realizar el mantenimiento y comprobaciones al resto de la instalación de alterna puesta en descargo según las gamas de mantenimiento', 'Verificar el par de apriete de las conexiones con ayuda de una llave dinamométrica según las indicaciones del fabricante'], '{"Aparatos de medida": ["Multímetro.", "Pinzas amperimétrica AC."], "Equipos de seguridad": ["Casco.", "Calzado de seguridad.", "Guantes de trabajo.", "Guantes aislantes.", "Chaleco reflectante."], "Herramientas": ["Procedimientos de trabajo para mantenimiento preventivo en plantas F.V.", "Registros de inspección para mantenimiento preventivo en plantas F.V.", "Documentación técnica de la instalación.", "Plano unifilar y de conexión de servicios auxiliares.", "Juego de herramientas de mano aisladas (juego de destornilladores, juego de llaves", "fijas y de carraca, juego de alicates, tijeras, etc.).", "61"]}'::jsonb) on conflict (numero) do nothing;
insert into public.procedimientos (numero, titulo, objeto, alcance, responsable, condicionantes, pasos, equipo) values ('22', 'COMPROBACIÓN DE LAS INFRAESTRUCTURAS DE LOS CENTROS PREFABRICADOS', 'El objeto de este procedimiento es comprobar que las instalaciones se encuentran en adecuadas condiciones de limpieza y conservación.', 'La totalidad de las instalaciones.', 'Personal de mantenimiento.', 'No existen condicionantes específicos para realizar este procedimiento. 63', ARRAY['Revisar que la pintura de paredes y estructuras no sean deficientes', 'Comprobar si existe acumulación de polvo', 'Verificar si existe materiales almacenados', 'Asegurar si existe iluminación suficiente y si hay un correcto funcionamiento del sistema de iluminación', 'Comprobar si existe dimensiones inadecuadas en pasillos', 'Observar si existe indicios de roedores', 'Verificar si existe y funciona correctamente el alumbrado de emergencia. Desconectando el equipo de la red o actuando sobre el interruptor de prueba', 'Comprobar si existe rejillas y pantallas de protección personal', 'Constatar si existen daños como abolladuras, cerraduras dañadas, etc', 'Estudiar la estanqueidad del centro, comprobando la inexistencia de humedad y el correcto estado de los paneles de aislamiento', 'Observar el correcto estado de los conductos de ventilación forzada, se prestará especial atención a posibles fisuras y agujeros así como a la limpieza de los filtros de aire', 'Comprobar el correcto funcionamiento de los equipos de ventilación o climatización, así como de los termostatos que los accionan', 'Se realizará una inspección visual para comprobar el estado de limpieza de las instalaciones. Las zonas cerradas deberán estar, en la medida de lo posible, limpias de polvo, arena, barro,…', 'También se revisará que no existe vegetación u otros elementos cercanos a los edificios que pueden provocar daños en los mismos, así como riesgo de incendios', 'Constatar la correcta identificación del centro y observar si está la documentación y planos referentes a la instalación', 'Observar el correcto estado de las canalizaciones y bandejas para que no presenten deformaciones, sobrecargas, etc', 'Inspeccionar el correcto estado de las instalaciones de fuerza como tomas de corriente', 'Comprobar la existencia del siguiente material de seguridad:', 'Extintor.  Banqueta aislante.  Guantes de goma aislantes.  Manivela accionamiento del ruptofusible.  Manivela accionamiento del seccionador.  Maneta extractora de fusibles.  Llave de apertura de celdas.  Placa de primeros auxilios.  Pértiga'], '{"Equipos de seguridad": ["Calzado de seguridad.", "Guantes de trabajo."], "Herramientas": ["Aspirador.", "Escalera."], "Equipos de limpieza y material consumible": ["Papel y trapos de limpieza.", "Guantes de látex.", "Agua y productos de limpieza no abrasivos (jabón, paño, cepillos etc.).", "Limpiador multiusos.", "Cepillo de cerdas de plástico blandas (300mm).", "Baqueta con mango extensible. (diámetro 100mm y mango 1m)."]}'::jsonb) on conflict (numero) do nothing;
insert into public.procedimientos (numero, titulo, objeto, alcance, responsable, condicionantes, pasos, equipo) values ('23', 'COMPROBACIÓN DEL CENTRO DE CONTROL Y DEL ALMACÉN', 'El objeto de este procedimiento es comprobar que las instalaciones del centro de control y del almacén están en las condiciones adecuadas de limpieza y conservación.', 'La totalidad del centro de control y del almacén incluyendo la instalación fotovoltaica del tejado, la instalación eléctrica y el aire acondicionado.', 'Personal de mantenimiento.', 'No existen condicionantes específicos para realizar este procedimiento. 67', ARRAY['Comprobar el estado de la pintura en paredes y estructura  Comprobar que el botiquín de primeros auxilios contiene el material necesario  Comprobar la existencia de acumulación de polvo  Comprobar la existencia de los equipos de repuestos y su correcto etiquetado en el', 'almacén', 'Comprobar el estado de la iluminación  Comprobar las correctas dimensiones de pasillos  Comprobar si existen indicios de roedores. Si es así aplicar tratamiento', 'antiroedores', 'Comprobar el correcto funcionamiento de las luces de emergencia  Comprobar el correcto funcionamiento del aire acondicionado  Comprobar el estado de los extintores. Si fuera necesario, reemplazarlos.  Comprobar la correcta fijación de las estanterías en el almacén ', 'Inspección visual del centro de control y del almacén en busca de polvo, arena, barro, etc', 'Comprobar que alrededor del centro de control y del almacén no existe vegetación', 'excesiva y no molesta para la entrada a los edificios', '11. REGISTROS', 'Se dejará constancia de los datos y medidas obtenidos durante la realización de los trabajos', 'Para ello se cumplimentará cada una de las gamas de trabajo, donde se reflejará el estado de cada uno de los elementos revisados, así como los valores obtenidos en las diferentes mediciones. Si alguno de los apartados del informe no fuera de aplicación para el equipo inspeccionado, se dejará constancia de ello mediante las siglas N/A', 'Se realizarán para todos los elementos de una planta fotovoltaica que estén dentro del alcance de este procedimiento'], '{"Equipos de seguridad": ["Calzado de seguridad.", "Guantes de trabajo."], "Herramientas": ["Aspiradora", "Escalera."], "Equipos de limpieza y material consumible": ["Papel y trapos de limpieza.", "Guantes de látex.", "Agua y productos de limpieza no abrasivos (jabón, paño, cepillos etc.).", "Limpiador multiusos.", "Cepillo de cerdas de plástico blandas (300mm).", "Baqueta con mango extensible. (diámetro 100mm y mango 1m)."]}'::jsonb) on conflict (numero) do nothing;
insert into public.procedimientos (numero, titulo, objeto, alcance, responsable, condicionantes, pasos, equipo) values ('24', 'Limpieza de módulos fotovoltaicos', 'Mantener los módulos fotovoltaicos limpios para asegurar la máxima captación de radiación y evitar puntos calientes por suciedad incrustada.', 'Todos los módulos de la instalación fotovoltaica programados en el cronograma.', 'Personal técnico de mantenimiento.', 'Realizar en horas de baja radiación cuando sea posible. No utilizar productos abrasivos ni disolventes. No verter agua directamente sobre las conexiones ni cajas de conexión.', ARRAY['Informar al responsable de la planta antes de comenzar los trabajos.', 'Revisar visualmente el estado de los paneles (roturas, arañazos, suciedad incrustada) antes de limpiar.', 'Humectar los paños o esponjas con agua y jabón no abrasivo.', 'Limpiar la superficie del módulo con movimientos suaves, evitando raspar el cristal ni las células.', 'No verter agua a presión directamente sobre el módulo ni sobre las cajas de conexión y conectores.', 'Retirar la humedad con un paño seco y limpio.', 'Verificar al terminar que no quedan restos de agua ni jabón en marcos ni conexiones.', 'Reportar cualquier daño detectado (roturas, delaminación, puntos calientes) como observación.'], '{"Equipos de seguridad": ["Casco", "Calzado de seguridad", "Guantes de trabajo", "Chaleco reflectante"], "Herramientas": ["Baqueta con mango extensible (diámetro 100mm, mango 1m)", "Cepillo de cerdas blandas (300mm)", "Esponja y paños no abrasivos"], "Equipos de limpieza y material consumible": ["Agua", "Jabón o producto de limpieza no abrasivo", "Trapos de limpieza", "Cepillo de plástico de cerdas blandas"]}'::jsonb) on conflict (numero) do nothing;
insert into public.procedimientos (numero, titulo, objeto, alcance, responsable, condicionantes, pasos, equipo) values ('25', 'Revisión y arranque del grupo electrógeno', 'Verificar el correcto estado y funcionamiento del grupo electrógeno de servicios auxiliares.', 'Grupo electrógeno de la planta.', 'Personal técnico cualificado.', 'Realizar las comprobaciones en frío antes del arranque. Seguir el manual del fabricante.', ARRAY['Verificar el nivel de combustible y aceite del grupo.', 'Comprobar el estado de la batería y sus conexiones.', 'Revisar visualmente fugas de combustible o aceite.', 'Comprobar el estado de los filtros de aire y combustible.', 'Realizar el arranque del grupo en modo manual y verificar que arranca correctamente.', 'Comprobar tensión y frecuencia de salida con el multímetro.', 'Verificar que no hay alarmas ni fallos en el panel de control.', 'Realizar una prueba de transferencia a la carga de servicios auxiliares si aplica.', 'Registrar los valores medidos y observaciones.'], '{"Equipos de seguridad": ["Casco", "Calzado de seguridad", "Guantes de trabajo", "Guantes aislantes"], "Herramientas": ["Multímetro", "Juego de herramientas de mano aisladas", "Linterna"]}'::jsonb) on conflict (numero) do nothing;
insert into public.procedimientos (numero, titulo, objeto, alcance, responsable, condicionantes, pasos, equipo) values ('26', 'Informe técnico mensual', 'Elaborar el informe técnico mensual de la planta con los datos de producción, mantenimientos realizados y estado de la instalación.', 'Toda la planta fotovoltaica.', 'Responsable de mantenimiento.', 'Recopilar la información del mes en curso antes de cerrar el informe.', ARRAY['Recopilar los datos de producción y energía generada del mes desde el sistema de monitorización.', 'Revisar las gamas de trabajo completadas durante el mes y su estado.', 'Incluir las incidencias y averías atendidas durante el mes.', 'Incluir el estado del stock de repuestos y material.', 'Redactar el informe con los datos y observaciones.', 'Entregar el informe al responsable de la planta.'], '{"Herramientas": ["PC portátil", "Registros de inspección del mes", "Datos del sistema de monitorización"]}'::jsonb) on conflict (numero) do nothing;
insert into public.procedimientos (numero, titulo, objeto, alcance, responsable, condicionantes, pasos, equipo) values ('27', 'Revisión de extintores', 'Verificar que los extintores de la planta están en condiciones operativas y dentro de su fecha de timbrado.', 'Todos los extintores de la instalación.', 'Personal de mantenimiento.', 'No manipular el precinto ni realizar pruebas que descarguen el extintor.', ARRAY['Verificar que el extintor se encuentra en su ubicación asignada y señalizada.', 'Comprobar que la presión del manómetro está en la zona verde.', 'Verificar que el precinto y el pasador están intactos.', 'Comprobar que la boquilla y la manguera están en buen estado.', 'Revisar la fecha de vencimiento del timbrado; si está vencido, gestionar el retimbrado.', 'Anotar cualquier extintor dañado o descargado para su reemplazo.'], '{"Equipos de seguridad": ["Calzado de seguridad", "Guantes de trabajo"], "Herramientas": ["Linterna"]}'::jsonb) on conflict (numero) do nothing;
insert into public.procedimientos (numero, titulo, objeto, alcance, responsable, condicionantes, pasos, equipo) values ('28', 'Revisión del sistema contra incendios', 'Verificar el estado operativo del sistema contra incendios de la planta.', 'Extintores y medios de extinción de la instalación.', 'Personal de mantenimiento.', 'Verificar la presencia de todos los medios de extinción según el plan de la planta.', ARRAY['Recorrer la planta verificando la presencia de extintores en todas las zonas obligatorias.', 'Comprobar el estado de cada extintor (presión, precinto, fecha de timbrado).', 'Verificar accesibilidad y señalización de los equipos de extinción.', 'Comprobar el estado de la red de contra incendios si existe.', 'Registrar cualquier deficiencia encontrada.'], '{"Equipos de seguridad": ["Calzado de seguridad", "Guantes de trabajo"], "Herramientas": ["Linterna"]}'::jsonb) on conflict (numero) do nothing;
