
-- ============================================================
-- SQL MIGRACIÓN SEGURA - MÓDULO MANTENIMIENTO - PLANTA LA INDEPENDENCIA
-- Ejecuta esto en Supabase: Project > SQL Editor > New query > Run
--
-- Instala el módulo de mantenimiento en una BD que ya tiene el
-- esquema de la web (tareas con descripcion/responsable):
--   * Tabla procedimientos (los 28 procedimientos).
--   * Columnas del cronograma en tareas (actividad, tecnico,
--     procedimientos, n, mes, semana, dia, horas, codigo, frecuencia...).
--   * Tablas perfiles y tarea_ejecuciones, RLS y bucket de fotos.
--   * Cronograma completo 2026 y estados normalizados a
--     pendiente / en_progreso / hecha.
-- SEGURO: el reseteo del cronograma solo borra filas con
-- procedimientos asignados; las tareas creadas manualmente desde la
-- web (descripcion/responsable) se conservan.
-- Es idempotente: se puede ejecutar varias veces sin romper nada.
-- ============================================================

create table if not exists public.procedimientos (
  id serial primary key,
  numero text not null unique,
  titulo text not null,
  objeto text,
  alcance text,
  responsable text,
  condicionantes text,
  pasos text[] not null default '{}',
  equipo jsonb not null default '{}'::jsonb
);

create table if not exists public.tareas (
  id uuid default gen_random_uuid() primary key,
  n int,
  mes text,
  semana int,
  dia text,
  fecha date,
  hora_inicio text,
  hora_fin text,
  duracion numeric,
  actividad text default '',
  codigo text default '',
  frecuencia text default '',
  tecnico text default '',
  estado text not null default 'pendiente',
  procedimientos text[] not null default '{}',
  descripcion text default '',
  area text default '',
  responsable text default '',
  prioridad text not null default 'normal',
  creado_por uuid references auth.users default auth.uid(),
  creado_en timestamptz default now(),
  archivada boolean not null default false
);

-- Si la tabla tareas ya existía con el esquema de la web o con una
-- versión anterior, estas instrucciones completan las columnas que
-- falten y normalizan valores por defecto. No borran la tabla.
alter table public.tareas add column if not exists n int;
alter table public.tareas add column if not exists mes text;
alter table public.tareas add column if not exists semana int;
alter table public.tareas add column if not exists dia text;
alter table public.tareas add column if not exists hora_inicio text;
alter table public.tareas add column if not exists hora_fin text;
alter table public.tareas add column if not exists duracion numeric;
alter table public.tareas add column if not exists actividad text default '';
alter table public.tareas add column if not exists codigo text default '';
alter table public.tareas add column if not exists frecuencia text default '';
alter table public.tareas add column if not exists tecnico text default '';
alter table public.tareas add column if not exists procedimientos text[] not null default '{}';
alter table public.tareas add column if not exists descripcion text default '';
alter table public.tareas add column if not exists area text default '';
alter table public.tareas add column if not exists responsable text default '';
alter table public.tareas add column if not exists prioridad text not null default 'normal';
alter table public.tareas add column if not exists creado_por uuid references auth.users default auth.uid();
alter table public.tareas add column if not exists creado_en timestamptz default now();
alter table public.tareas add column if not exists archivada boolean not null default false;

-- Compatibilidad web/móvil: estado 'pendiente' por defecto y campos que
-- la web no rellena al crear una tarea manual sin NOT NULL.
alter table public.tareas alter column estado set default 'pendiente';
alter table public.tareas alter column actividad drop not null;
alter table public.tareas alter column actividad set default '';
alter table public.tareas alter column tecnico drop not null;
alter table public.tareas alter column tecnico set default '';

create table if not exists public.perfiles (
  user_id uuid references auth.users(id) on delete cascade primary key,
  tecnico text not null,
  actualizado_en timestamptz default now()
);

create table if not exists public.tarea_ejecuciones (
  id uuid default gen_random_uuid() primary key,
  tarea_id uuid references public.tareas(id) on delete cascade not null,
  user_id uuid references auth.users(id) default auth.uid(),
  foto_url text,
  observaciones text,
  ejecutado_en timestamptz default now()
);

create index if not exists idx_tareas_tecnico_fecha on public.tareas (tecnico, fecha);
create index if not exists idx_ejecuciones_tarea on public.tarea_ejecuciones (tarea_id);

-- Seguridad (RLS)
alter table public.procedimientos enable row level security;
alter table public.tareas enable row level security;
alter table public.perfiles enable row level security;
alter table public.tarea_ejecuciones enable row level security;

drop policy if exists "procedimientos_ver" on public.procedimientos;
create policy "procedimientos_ver" on public.procedimientos
  for select to authenticated using (true);

drop policy if exists "tareas_ver" on public.tareas;
create policy "tareas_ver" on public.tareas
  for select to authenticated using (true);

drop policy if exists "tareas_actualizar" on public.tareas;
create policy "tareas_actualizar" on public.tareas
  for update to authenticated using (true);

drop policy if exists "tareas_crear" on public.tareas;
create policy "tareas_crear" on public.tareas
  for insert to authenticated with check (true);

drop policy if exists "tareas_borrar" on public.tareas;
create policy "tareas_borrar" on public.tareas
  for delete to authenticated using (true);

drop policy if exists "perfiles_ver_propios" on public.perfiles;
create policy "perfiles_ver_propios" on public.perfiles
  for select to authenticated using (auth.uid() = user_id);

drop policy if exists "perfiles_crear_propios" on public.perfiles;
create policy "perfiles_crear_propios" on public.perfiles
  for insert to authenticated with check (auth.uid() = user_id);

drop policy if exists "perfiles_actualizar_propios" on public.perfiles;
create policy "perfiles_actualizar_propios" on public.perfiles
  for update to authenticated using (auth.uid() = user_id);

drop policy if exists "ejecuciones_ver" on public.tarea_ejecuciones;
create policy "ejecuciones_ver" on public.tarea_ejecuciones
  for select to authenticated using (true);

drop policy if exists "ejecuciones_crear" on public.tarea_ejecuciones;
create policy "ejecuciones_crear" on public.tarea_ejecuciones
  for insert to authenticated with check (auth.uid() = user_id);

-- Bucket de fotos de tareas
values (
  'fotos-tareas',
  'fotos-tareas',
  false,
  10485760,
  array['image/jpeg', 'image/png', 'image/webp']
)
on conflict (id) do nothing;

drop policy if exists "fotos_tareas_ver" on storage.objects;
create policy "fotos_tareas_ver"
  on storage.objects for select
  to authenticated
  using (bucket_id = 'fotos-tareas');

drop policy if exists "fotos_tareas_subir" on storage.objects;
create policy "fotos_tareas_subir"
  on storage.objects for insert
  to authenticated
  with check (bucket_id = 'fotos-tareas');

drop policy if exists "fotos_tareas_actualizar" on storage.objects;
create policy "fotos_tareas_actualizar"
  on storage.objects for update
  to authenticated
  using (bucket_id = 'fotos-tareas');

drop policy if exists "fotos_tareas_borrar" on storage.objects;
create policy "fotos_tareas_borrar"
  on storage.objects for delete
  to authenticated
  using (bucket_id = 'fotos-tareas');

-- MIGRACIÓN SEGURA: solo se resetea el cronograma (filas con procedimientos).
-- Las tareas creadas manualmente desde la web (descripcion/responsable,
-- sin procedimientos) NO se borran.
delete from public.tareas where procedimientos is not null and procedimientos <> '{}';

-- ============================================================
-- ESTADOS UNIFICADOS (web + app móvil): pendiente / en_progreso / hecha
--  1) Los estados heredados (Realizado, Programado (X), Atrasada, ...)
--     se mapean a los tres valores que usan la web y la app móvil.
--  2) El cronograma de enero a julio de 2026 se considera ejecutado
--     ('hecha'); las tareas de agosto en adelante quedan 'pendiente'.
-- ============================================================

update public.tareas
set estado = case
  when lower(coalesce(estado, '')) in ('realizado', 'realizada', 'completada', 'completado', 'hecho', 'hecha') then 'hecha'
  when lower(coalesce(estado, '')) in ('en progreso', 'en_progreso', 'progreso') then 'en_progreso'
  else 'pendiente'
end;

update public.tareas
set estado = 'hecha'
where estado <> 'hecha'
  and fecha <= '2026-07-31';

-- Asegura que solo se puedan guardar estados válidos (web y móvil)
do $$
begin
  if not exists (
    select 1 from pg_constraint
    where conname = 'tareas_estado_unificado_check'
      and conrelid = 'public.tareas'::regclass
  ) then
    alter table public.tareas
      add constraint tareas_estado_unificado_check
      check (estado in ('pendiente', 'en_progreso', 'hecha'));
  end if;
end $$;

-- Verificación: cuántas tareas quedaron por estado
select estado, count(*) as total
from public.tareas
group by estado
order by estado;
